    public function getCleanYoutubeUrl(string $fieldName): string
    {
        $url = $this->{$fieldName};
        if (blank($url)) {
            return '';
        }

        preg_match('/(?:v=|\/v\/|watch\?v=|youtu\.be\/|embed\/)([a-zA-Z0-9_-]{11})/', $url, $matches);

        if (isset($matches[1])) {
            return 'https://www.youtube.com/embed/' . $matches[1];
        }

        return $url;
    }

